<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, type StudyDocument, type DocumentPage } from '../lib/api'
import { highlightQuote, selectionError } from '../lib/documents'
import { message } from '../lib/state'
import Icon from '../components/Icon.vue'
import PdfCanvas from '../components/PdfCanvas.vue'
const route=useRoute(),router=useRouter(),document=ref<StudyDocument>(),pages=ref<DocumentPage[]>([]),loading=ref(true),error=ref(''),page=ref(1),start=ref(1),end=ref(1)
const current=computed(()=>pages.value.find(p=>p.page===page.value)),quote=computed(()=>String(route.query.quote||'')),chunks=computed(()=>highlightQuote(current.value?.text||'',quote.value))
const rangeError=computed(()=>selectionError(pages.value,start.value,end.value))
function setPage(value:number){if(!document.value)return;page.value=Math.min(document.value.pageCount,Math.max(1,Math.trunc(value)||1));void router.replace({query:{...route.query,page:page.value}})}
watch(()=>route.query.page,value=>{const num=Number(value)||1;if(document.value)page.value=Math.min(document.value.pageCount,Math.max(1,Math.trunc(num)))})
let generation=0,disposed=false
async function load(){const token=++generation,id=String(route.params.id);const active=()=>!disposed&&token===generation&&String(route.params.id)===id;loading.value=true;error.value='';try{const data=await api.document(id);if(!active())return;document.value=data.document;pages.value=data.pages;setPage(Number(route.query.page)||1);start.value=page.value;end.value=page.value}catch(e){if(active())error.value=message(e)}finally{if(active())loading.value=false}}
onBeforeUnmount(()=>{disposed=true;generation++})
function create(){if(!rangeError.value)void router.push({path:'/sets/new',query:{documentId:document.value!.id,startPage:start.value,endPage:end.value}})}
onMounted(load)
</script>
<template><div class="page-container reader-page"><RouterLink to="/documents" class="back-link"><Icon name="left"/>返回教材库</RouterLink><div v-if="loading" class="loading">正在打开教材…</div><div v-else-if="error" class="empty-state"><Icon name="lock"/><h2>暂时无法打开原教材</h2><p>{{error}}。教材可能属于其他账户，或已删除；题集中的引用快照不受影响。</p><button class="button" @click="load">重试</button></div><template v-else-if="document"><header class="page-heading"><div><span class="topic-label">私有教材 · 原文件与提取文字</span><h1>{{document.title}}</h1><p>{{document.pageCount}} 物理页 · {{document.textPageCount}} 页有文字 · 与印刷页码可能不同</p></div></header><p v-for="warning in document.warnings" :key="warning" class="inline-note"><Icon name="warning"/>{{warning}}</p><div class="reader-toolbar"><div class="row"><button class="icon-button" aria-label="上一页" :disabled="page<=1" @click="setPage(page-1)"><Icon name="left"/></button><label class="page-input">物理页<input :value="page" type="number" min="1" :max="document.pageCount" @change="setPage(Number(($event.target as HTMLInputElement).value))"/></label><span class="muted">/ {{document.pageCount}}</span><button class="icon-button" aria-label="下一页" :disabled="page>=document.pageCount" @click="setPage(page+1)"><Icon name="right"/></button></div><span class="small muted">高亮仅对应提取文字，不代表 PDF 坐标定位</span></div><div class="reader-grid"><PdfCanvas :document-id="document.id" :page="page"/><section class="extracted-panel"><div class="section-head"><h2>本页文字</h2><span class="small muted">{{current?.charCount||0}} 字</span></div><p v-if="!current?.text" class="inline-note">本页没有可提取文字，不提供 OCR。</p><p v-else class="extracted-text"><template v-for="(chunk,i) in chunks" :key="i"><mark v-if="chunk.highlight">{{chunk.text}}</mark><template v-else>{{chunk.text}}</template></template></p><p v-if="quote&&!chunks.some(c=>c.highlight)" class="inline-note">当前页未定位到此引文，请核对原页与引用快照。</p></section></div><section class="reader-selection surface"><div><h2>用选定页创建题集</h2><p class="muted small">可以手工绑定引用，也可以配置模型后按页生成</p></div><label>起始页<input v-model.number="start" type="number" min="1" :max="document.pageCount"/></label><label>结束页<input v-model.number="end" type="number" min="1" :max="document.pageCount"/></label><button class="button primary" :disabled="!!rangeError" @click="create">创建题集<Icon name="right"/></button><p v-if="rangeError" class="error">{{rangeError}}</p></section></template></div></template>
